// ---------------------------------------------------------------------
// Subjects (pronouns) in the fixed order used throughout the source doc.
// ---------------------------------------------------------------------
const SUBJECTS = [
  { id: "i", en: "I", bn: "আমি", isThirdSingular: false, isI: true },
  { id: "we", en: "We", bn: "আমরা", isThirdSingular: false },
  { id: "you_sg", en: "You", bn: "তুমি", isThirdSingular: false },
  { id: "you_pl", en: "You", bn: "তোমরা", isThirdSingular: false },
  { id: "he", en: "He", bn: "সে (পু)", isThirdSingular: true },
  { id: "she", en: "She", bn: "সে (ম)", isThirdSingular: true },
  { id: "it", en: "It", bn: "এটা", isThirdSingular: true },
  { id: "they", en: "They", bn: "তারা", isThirdSingular: false },
];

function auxDo(subj) { return subj.isThirdSingular ? "does" : "do"; }
function auxBe(subj) { return subj.isI ? "am" : subj.isThirdSingular ? "is" : "are"; }
function pastBe(subj) { return (subj.isI || subj.isThirdSingular) ? "was" : "were"; }
function auxHave(subj) { return subj.isThirdSingular ? "has" : "have"; }
function cap(s) { return s.charAt(0).toUpperCase() + s.slice(1); }
function subjLower(s) { return s.isI ? "I" : s.en.toLowerCase(); }

// ---------------------------------------------------------------------
// Regular-verb conjugation rules (used when a verb isn't in the
// irregular table). Standard English spelling rules; not exhaustive for
// every edge case, but correct for the common practice verbs.
// ---------------------------------------------------------------------
const VOWELS = "aeiou";

function isConsonant(ch) {
  return /[a-z]/.test(ch) && VOWELS.indexOf(ch) === -1;
}

function isShortStressedCVC(base) {
  if (base.length < 3) return false;
  if (/[wxy]$/.test(base)) return false;
  const last3 = base.slice(-3);
  return (
    isConsonant(last3[0]) &&
    VOWELS.indexOf(last3[1]) !== -1 &&
    isConsonant(last3[2]) &&
    base.length <= 6 // rough one-syllable heuristic for common practice verbs
  );
}

function sForm(base) {
  if (/(?:[sxz]|ch|sh|o)$/.test(base)) return base + "es";
  if (/[^aeiou]y$/.test(base)) return base.slice(0, -1) + "ies";
  return base + "s";
}

function ingForm(base) {
  if (base === "be") return "being";
  if (/ie$/.test(base)) return base.slice(0, -2) + "ying";
  if (/[^aeiou]e$/.test(base) && !/ee$/.test(base)) return base.slice(0, -1) + "ing";
  if (isShortStressedCVC(base)) return base + base.slice(-1) + "ing";
  return base + "ing";
}

function edForm(base) {
  if (/e$/.test(base)) return base + "d";
  if (/[^aeiou]y$/.test(base)) return base.slice(0, -1) + "ied";
  if (isShortStressedCVC(base)) return base + base.slice(-1) + "ed";
  return base + "ed";
}

const IRREGULAR_MAP = {};
IRREGULAR_VERBS.forEach((v) => {
  const key = v.v1.toLowerCase();
  if (key === "be") return; // handled by the dedicated be-verb charts, not the do-pattern
  IRREGULAR_MAP[key] = {
    base: key,
    past: v.v2.split(/[,/]/)[0].trim(),
    pp: v.v3.split(/[,/]/)[0].trim(),
  };
});

function conjugate(rawVerb) {
  const base = (rawVerb || "do").trim().toLowerCase() || "do";
  const irr = IRREGULAR_MAP[base];
  return {
    base,
    sForm: sForm(base),
    ingForm: ingForm(base),
    pastForm: irr ? irr.past : edForm(base),
    ppForm: irr ? irr.pp : edForm(base),
  };
}

function verbBnMeaning(rawVerb) {
  const base = (rawVerb || "do").trim().toLowerCase();
  const entry = IRREGULAR_VERBS.find((v) => v.v1.toLowerCase() === base);
  return entry ? entry.bn : "";
}

// ---------------------------------------------------------------------
// The 12 "do-pattern" chapters: any verb can be substituted in, exactly
// as the source doc instructs ("Do" ভার্বের স্থানে অন্য verb বসিয়ে...).
// ---------------------------------------------------------------------
const DO_PATTERN_BUILDERS = {
  indefinite: (f, s) => ({
    pos: `${s.en} ${s.isThirdSingular ? f.sForm : f.base}`,
    neg: `${s.en} ${auxDo(s)} not ${f.base}`,
    int: `${cap(auxDo(s))} ${subjLower(s)} ${f.base}?`,
  }),
  continuous: (f, s) => ({
    pos: `${s.en} ${auxBe(s)} ${f.ingForm}`,
    neg: `${s.en} ${auxBe(s)} not ${f.ingForm}`,
    int: `${cap(auxBe(s))} ${subjLower(s)} ${f.ingForm}?`,
  }),
  perfect: (f, s) => ({
    pos: `${s.en} ${auxHave(s)} ${f.ppForm}`,
    neg: `${s.en} ${auxHave(s)} not ${f.ppForm}`,
    int: `${cap(auxHave(s))} ${subjLower(s)} ${f.ppForm}?`,
  }),
  perfect_continuous: (f, s) => ({
    pos: `${s.en} ${auxHave(s)} been ${f.ingForm} for/since ...`,
    neg: `${s.en} ${auxHave(s)} not been ${f.ingForm} for/since ...`,
    int: `${cap(auxHave(s))} ${subjLower(s)} been ${f.ingForm} for/since ...?`,
  }),
};

const PAST_DO_PATTERN_BUILDERS = {
  indefinite: (f, s) => ({
    pos: `${s.en} ${f.pastForm}`,
    neg: `${s.en} did not ${f.base}`,
    int: `Did ${subjLower(s)} ${f.base}?`,
  }),
  continuous: (f, s) => ({
    pos: `${s.en} ${pastBe(s)} ${f.ingForm}`,
    neg: `${s.en} ${pastBe(s)} not ${f.ingForm}`,
    int: `${cap(pastBe(s))} ${subjLower(s)} ${f.ingForm}?`,
  }),
  perfect: (f, s) => ({
    pos: `${s.en} had ${f.ppForm}`,
    neg: `${s.en} had not ${f.ppForm}`,
    int: `Had ${subjLower(s)} ${f.ppForm}?`,
  }),
  perfect_continuous: (f, s) => ({
    pos: `${s.en} had been ${f.ingForm} for/since ...`,
    neg: `${s.en} had not been ${f.ingForm} for/since ...`,
    int: `Had ${subjLower(s)} been ${f.ingForm} for/since ...?`,
  }),
};

const FUTURE_DO_PATTERN_BUILDERS = {
  indefinite: (f, s) => ({
    pos: `${s.en} will ${f.base}`,
    neg: `${s.en} will not ${f.base}`,
    int: `Will ${subjLower(s)} ${f.base}?`,
  }),
  continuous: (f, s) => ({
    pos: `${s.en} will be ${f.ingForm}`,
    neg: `${s.en} will not be ${f.ingForm}`,
    int: `Will ${subjLower(s)} be ${f.ingForm}?`,
  }),
  perfect: (f, s) => ({
    pos: `${s.en} will have ${f.ppForm}`,
    neg: `${s.en} will not have ${f.ppForm}`,
    int: `Will ${subjLower(s)} have ${f.ppForm}?`,
  }),
  perfect_continuous: (f, s) => ({
    pos: `${s.en} will have been ${f.ingForm} ... until`,
    neg: `${s.en} will not have been ${f.ingForm} ... until`,
    int: `Will ${subjLower(s)} have been ${f.ingForm} ... until?`,
  }),
};

const BUILDERS_BY_GROUP = {
  present: DO_PATTERN_BUILDERS,
  past: PAST_DO_PATTERN_BUILDERS,
  future: FUTURE_DO_PATTERN_BUILDERS,
};

// ---------------------------------------------------------------------
// Static be/have reference charts (group: be | have). These describe the
// verbs "be" and "have" themselves (state / possession) rather than an
// auxiliary + action-verb combination, so they are not verb-substitutable
// — they're the same 6 charts for every chapter, shown as fixed reference.
// ---------------------------------------------------------------------
function buildAuxChart(group, kind) {
  return SUBJECTS.map((s) => {
    let pos, neg, int;
    if (kind === "be") {
      const aux = group === "present" ? auxBe(s) : group === "past" ? pastBe(s) : "will be";
      pos = `${s.en} ${aux} ...`;
      neg = `${s.en} ${aux} not ...`;
      int = group === "future" ? `Will ${subjLower(s)} be ...?` : `${cap(aux)} ${subjLower(s)} ...?`;
    } else {
      const aux = group === "present" ? auxHave(s) : group === "past" ? "had" : "will have";
      pos = `${s.en} ${aux} ...`;
      neg = `${s.en} ${aux} not ...`;
      int = group === "future" ? `Will ${subjLower(s)} have ...?` : `${cap(aux)} ${subjLower(s)} ...?`;
    }
    return { id: s.id, en: s.en, bn: s.bn, pos, neg, int };
  });
}

